        var mod = makeModule();
        var t1 = commentTracker();
        mod.postOutcomeSummaryComment(t1, 'PROJ-100', 'https://jira.example.com', { created: [], skipped: [] });
        assert.equal(t1.calls.comment.length, 0, 'nothing done — no comment');

